// Kinematics for the SO-101, driven directly by the URDF joint table in
// public/models/so101/so101.json (generated by scripts/build-so101.mjs).
//
// Frames follow the URDF: base frame is Z-up, metres, radians. The
// tool-centre point (TCP) takes its orientation from the URDF's
// `gripper_frame_link` (+Z points out of the gripper: the approach
// direction), but its position is moved to the middle of the jaw gap.
// The URDF frame sits on the fixed jaw's inner face, which is the wrong
// point to servo a cube's centre to.

import * as THREE from "three";

export type JointSpec = {
  name: string;
  type: "revolute" | "fixed" | string;
  parent: string;
  child: string;
  xyz: [number, number, number];
  rpy: [number, number, number];
  axis: [number, number, number];
  lower: number;
  upper: number;
};

export type MeshPart = {
  material: string;
  positions: { offset: number; count: number };
  indices: { offset: number; count: number };
};

export type ArmManifest = {
  source: string;
  bytes: number;
  links: { name: string; parts: MeshPart[] }[];
  joints: JointSpec[];
};

// the five arm joints, base to wrist, in the order every q vector uses
export const ARM_JOINTS = [
  "shoulder_pan",
  "shoulder_lift",
  "elbow_flex",
  "wrist_flex",
  "wrist_roll",
] as const;
export const GRIPPER_JOINT = "gripper";
const TCP_JOINT = "gripper_frame_joint";

// centre of a CUBE-sized object held in the jaws, in the gripper_link
// frame (metres). Measured from the decimated meshes: the fixed jaw's
// inner face is at x = -7.9 mm and the fingertips end at z = -104.4 mm;
// a 24 mm cube against that face is centred 12 mm further in, and this
// height leaves the fingertips 3 mm above the table at grasp.
export const GRASP_CENTRE: [number, number, number] = [0.0041, -0.0002, -0.0954];

export function originMatrix(xyz: number[], rpy: number[]): THREE.Matrix4 {
  // URDF rpy is R = Rz(yaw) Ry(pitch) Rx(roll), i.e. three's 'ZYX' order
  const q = new THREE.Quaternion().setFromEuler(
    new THREE.Euler(rpy[0], rpy[1], rpy[2], "ZYX")
  );
  return new THREE.Matrix4().compose(
    new THREE.Vector3(xyz[0], xyz[1], xyz[2]),
    q,
    new THREE.Vector3(1, 1, 1)
  );
}

export type Chain = {
  origins: THREE.Matrix4[]; // one per arm joint
  axes: THREE.Vector3[];
  lower: number[];
  upper: number[];
  tcp: THREE.Matrix4; // fixed offset from the last arm joint to the TCP
};

export function buildChain(joints: JointSpec[]): Chain {
  const byName = new Map(joints.map((j) => [j.name, j]));
  const arm = ARM_JOINTS.map((n) => {
    const j = byName.get(n);
    if (!j) throw new Error(`missing joint ${n}`);
    return j;
  });
  const tcp = byName.get(TCP_JOINT);
  if (!tcp) throw new Error(`missing joint ${TCP_JOINT}`);
  return {
    origins: arm.map((j) => originMatrix(j.xyz, j.rpy)),
    axes: arm.map((j) => new THREE.Vector3(...j.axis).normalize()),
    lower: arm.map((j) => j.lower),
    upper: arm.map((j) => j.upper),
    tcp: originMatrix(GRASP_CENTRE, tcp.rpy),
  };
}

const scratchRot = new THREE.Matrix4();

/** TCP pose in the base frame for joint vector q (length 5). */
export function forward(chain: Chain, q: ArrayLike<number>, out = new THREE.Matrix4()) {
  out.identity();
  for (let i = 0; i < chain.origins.length; i++) {
    out.multiply(chain.origins[i]);
    out.multiply(scratchRot.makeRotationAxis(chain.axes[i], q[i]));
  }
  return out.multiply(chain.tcp);
}

const fkPose = new THREE.Matrix4();
const tmpVec = new THREE.Vector3();

/** writes TCP position and approach axis (+Z of the TCP frame) */
function tcpState(chain: Chain, q: ArrayLike<number>, pos: THREE.Vector3, approach: THREE.Vector3) {
  forward(chain, q, fkPose);
  pos.setFromMatrixPosition(fkPose);
  approach.setFromMatrixColumn(fkPose, 2).normalize();
}

/** jaw closing direction (+X of the gripper link) in the base frame */
export function jawAxis(chain: Chain, q: ArrayLike<number>, out = new THREE.Vector3()) {
  forward(chain, q, fkPose);
  // TCP frame is gripper_link rotated pi about Y, so gripper +X is TCP -X
  return out.setFromMatrixColumn(fkPose, 0).negate().normalize();
}

export type IkTarget = {
  position: THREE.Vector3;
  approach: THREE.Vector3; // desired unit approach direction
  /** metres of position error one radian of approach error is worth */
  approachWeight: number;
};

const IK_JOINTS = 4; // pan, lift, elbow, flex; wrist roll is set directly
const FD_STEP = 1e-5;
const pos0 = new THREE.Vector3();
const app0 = new THREE.Vector3();
const pos1 = new THREE.Vector3();
const app1 = new THREE.Vector3();

function residual(target: IkTarget, pos: THREE.Vector3, app: THREE.Vector3, out: number[]) {
  out[0] = target.position.x - pos.x;
  out[1] = target.position.y - pos.y;
  out[2] = target.position.z - pos.z;
  tmpVec.crossVectors(app, target.approach).multiplyScalar(target.approachWeight);
  out[3] = tmpVec.x;
  out[4] = tmpVec.y;
  out[5] = tmpVec.z;
  // cross product vanishes at 180 deg too; push away from the flipped solution
  if (app.dot(target.approach) < 0) out[3] += target.approachWeight;
}

/** solves A x = b in place for a small dense system (Gaussian elimination) */
function solve(A: number[][], b: number[]): number[] {
  const n = b.length;
  for (let c = 0; c < n; c++) {
    let p = c;
    for (let r = c + 1; r < n; r++) if (Math.abs(A[r][c]) > Math.abs(A[p][c])) p = r;
    [A[c], A[p]] = [A[p], A[c]];
    [b[c], b[p]] = [b[p], b[c]];
    for (let r = c + 1; r < n; r++) {
      const f = A[r][c] / A[c][c];
      for (let k = c; k < n; k++) A[r][k] -= f * A[c][k];
      b[r] -= f * b[c];
    }
  }
  const x = new Array(n).fill(0);
  for (let r = n - 1; r >= 0; r--) {
    let s = b[r];
    for (let k = r + 1; k < n; k++) s -= A[r][k] * x[k];
    x[r] = s / A[r][r];
  }
  return x;
}

export type IkResult = { positionError: number; approachError: number; iterations: number };

/**
 * Damped-least-squares IK on the first four joints, warm-started from q
 * (modified in place). The wrist roll q[4] is held fixed. Each joint's
 * Jacobian column is taken by finite differences of the real chain, so
 * this works straight off the URDF without hand-derived geometry.
 */
export function solveIk(
  chain: Chain,
  q: number[],
  target: IkTarget,
  maxIterations = 30,
  damping = 0.01
): IkResult {
  const e = new Array(6).fill(0);
  const e1 = new Array(6).fill(0);
  const J: number[][] = Array.from({ length: 6 }, () => new Array(IK_JOINTS).fill(0));
  let it = 0;

  for (; it < maxIterations; it++) {
    tcpState(chain, q, pos0, app0);
    residual(target, pos0, app0, e);
    if (Math.hypot(e[0], e[1], e[2]) < 2e-4 && Math.hypot(e[3], e[4], e[5]) < 2e-4) break;

    for (let j = 0; j < IK_JOINTS; j++) {
      const saved = q[j];
      q[j] = saved + FD_STEP;
      tcpState(chain, q, pos1, app1);
      residual(target, pos1, app1, e1);
      q[j] = saved;
      // residual = target - f(q), so df/dq = -(e1 - e) / h
      for (let r = 0; r < 6; r++) J[r][j] = -(e1[r] - e[r]) / FD_STEP;
    }

    // (J^T J + lambda^2 I) dq = J^T e
    const A: number[][] = Array.from({ length: IK_JOINTS }, () => new Array(IK_JOINTS).fill(0));
    const b = new Array(IK_JOINTS).fill(0);
    for (let i = 0; i < IK_JOINTS; i++) {
      for (let k = 0; k < IK_JOINTS; k++) {
        let s = 0;
        for (let r = 0; r < 6; r++) s += J[r][i] * J[r][k];
        A[i][k] = s + (i === k ? damping * damping : 0);
      }
      let s = 0;
      for (let r = 0; r < 6; r++) s += J[r][i] * e[r];
      b[i] = s;
    }
    const dq = solve(A, b);
    for (let j = 0; j < IK_JOINTS; j++) {
      const step = Math.max(-0.3, Math.min(0.3, dq[j]));
      q[j] = Math.max(chain.lower[j], Math.min(chain.upper[j], q[j] + step));
    }
  }

  tcpState(chain, q, pos0, app0);
  return {
    positionError: pos0.distanceTo(target.position),
    approachError: Math.acos(Math.max(-1, Math.min(1, app0.dot(target.approach)))),
    iterations: it,
  };
}

export function tcpPosition(chain: Chain, q: ArrayLike<number>, out = new THREE.Vector3()) {
  return out.setFromMatrixPosition(forward(chain, q, fkPose));
}

/** quintic minimum-jerk blend, s in [0, 1] */
export function minJerk(s: number) {
  const t = Math.max(0, Math.min(1, s));
  return t * t * t * (10 + t * (-15 + 6 * t));
}
